import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';

const read=p=>readFileSync(new URL('../'+p,import.meta.url),'utf8');
const scope={};
Function('window',read('pandora-os-character-calculator.js'))(scope);
const C=scope.PandoraOSCalculator;
const items=JSON.parse(read('data/os/items.json'));

// Independent client observations, NOT generated by the calculator.
// Old unrepeatable Elf/Archer Heavy Crossbow 50–74 fixture is retired.
// Same-weapon sequences distinguish Strength, refinement and War Cry.
// Opposite-PEN same-W spear/pike test distinguishes individual PEN from fixed 75.
const rider=[
 [1482,56,174,150,'Zephyr +0'],
 [1451,56,174,136,'Piercing Pike +0'],
 [1482,56,213,184,'Zephyr +0 / War Cry'],
 [1451,56,213,167,'Piercing Pike +0 / War Cry'],
 [1483,56,219,189,'Strong Zephyr +8'],
 [1483,56,266,229,'Strong Zephyr +8 / War Cry'],
 [1483,56,218,188,'Strong Zephyr +8 / STR 71'],
 [1483,56,265,228,'Strong Zephyr +8 / War Cry / STR 70']
];
const hunter=[
 [2442,41,87,70,'Fire Djinn +0 / STR 6'],
 [2411,41,75,60,'Heavy Crossbow +0 / STR 6'],
 [2442,41,95,76,'Fire Djinn +0 / STR 20'],
 [2411,41,83,67,'Heavy Crossbow +0 / STR 20'],
 [2442,41,98,79,'Fire Djinn +1 / STR 20'],
 [2411,41,89,72,'Heavy Crossbow +2 / STR 20'],
 ...[[22,80,99],[23,80,99],[24,80,100],[25,80,100],
  [26,81,101],[27,81,101],[28,82,102],[29,82,102],[30,84,105]]
  .map(([str,min,max])=>[2442,41,max,min,'Fire Djinn +1 / STR '+str]),
 ...[[22,72,90],[23,72,90],[24,73,91],[25,73,91],
  [26,74,92],[27,74,92],[28,75,93],[29,75,93],[30,76,95]]
  .map(([str,min,max])=>[2411,41,max,min,'Heavy Crossbow +2 / STR '+str])
];
const bogadur=[[9,10,13],[10,11,14],[11,11,14],[12,11,15],[13,11,15],
 [15,12,16],[16,13,17],[17,13,17],[18,13,18]]
 .map(([str,min,max])=>[21,5,max,min,'Short Sword / STR '+str]);

test('game catalog PEN differs across equal-attack spear/pike, is identical for both crossbows',()=>{
 assert.deepEqual([items[1482].W,items[1451].W],[90,90]);
 assert.deepEqual([items[1482].PEN,items[1451].PEN],[80,120]);
 assert.deepEqual([items[2442].W,items[2411].W],[79,67]);
 assert.deepEqual([items[2442].PEN,items[2411].PEN],[90,90]);
});

test('41 independent client min–max readings match double floor with native weapon PEN',()=>{
 assert.deepEqual([rider.length,hunter.length,bogadur.length],[8,24,9]);
 for(const [id,trained,max,expectedMin,label] of [...rider,...hunter,...bogadur]){
  const weapon=items[id],branch=weapon.kind==='POLE_ARM'?'thrust':
   weapon.kind==='1H_SWORD'?'slash':'archery';
  const calculated=C.characterSheetPhysicalAttackRange({
   maximum:max,weapon,branchMasteries:{[branch]:trained}});
  assert.ok(calculated,label);
  assert.equal(calculated.maximum,max,label);
  assert.equal(calculated.minimum,expectedMin,label);
  assert.equal(calculated.pen,weapon.PEN,label);
  assert.equal(calculated.mastery,trained,label);
 }
});

test('PEN, not weapon base W, controls minimum at fixed max and proficiency',()=>{
 const z=C.characterSheetPhysicalAttackRange({
  maximum:174,weapon:items[1482],branchMasteries:{thrust:56}});
 const p=C.characterSheetPhysicalAttackRange({
  maximum:174,weapon:items[1451],branchMasteries:{thrust:56}});
 assert.deepEqual([z.minimum,z.rate,p.minimum,p.rate],[150,14,136,22]);
 assert.equal(z.maximum,p.maximum);
 // Nearest-even web combat formula would give Zephyr minimum 148, not 150.
 const webRate=Math.round(100*items[1482].PEN/(200+6*56));
 assert.equal(webRate,15);
 assert.equal(174-Math.floor(174*webRate/100),148);
});

test('trained green, not historical green or total tactics, changes weapon spread',()=>{
 const observed=C.characterSheetPhysicalAttackRange({
  maximum:105,weapon:items[2442],branchMasteries:{archery:41,assassin:3,
   traps:21,evade:3,craft:4,slash:4}});
 const retired=C.characterSheetPhysicalAttackRange({
  maximum:105,weapon:items[2442],branchMasteries:{archery:54}});
 assert.deepEqual([observed.minimum,observed.rate],[84,20]);
 assert.notEqual(retired.rate,observed.rate);
});

test('250 synthetic variants check boundedness, monotonicity and exact double floors',()=>{
 const pens=[20,30,40,50,60,65,75,80,90,120],masteries=[0,5,10,41,56];
 const maxes=[13,74,87,174,266];
 let count=0;
 for(const pen of pens)for(const mastery of masteries)for(const maximum of maxes){
  const weapon={kind:'CROSSBOW',slot:'weapon',PEN:pen};
  const r=C.characterSheetPhysicalAttackRange({
   maximum,weapon,branchMasteries:{archery:mastery}});
  const rate=Math.floor(100*pen/(200+6*mastery));
  assert.deepEqual([r.minimum,r.maximum,r.rate],
   [maximum-Math.floor(maximum*rate/100),maximum,rate]);
  assert.ok(r.minimum>=0&&r.minimum<=maximum);
  const next=C.characterSheetPhysicalAttackRange({
   maximum,weapon,branchMasteries:{archery:mastery+1}});
  assert.ok(next.minimum>=r.minimum);
  count++;
 }
 assert.equal(count,250);
});

test('invalid weapon, PEN, mastery or maximum never fabricates a minimum',()=>{
 const known=items[2442];
 for(const opts of [
  {maximum:100,weapon:null,branchMasteries:{archery:41}},
  {maximum:100,weapon:{kind:'UNKNOWN',PEN:90},branchMasteries:{archery:41}},
  {maximum:100,weapon:{kind:'CROSSBOW'},branchMasteries:{archery:41}},
  {maximum:100,weapon:known,branchMasteries:{}},
  {maximum:100,weapon:known,branchMasteries:{archery:-1}},
  {maximum:-1,weapon:known,branchMasteries:{archery:41}},
  {maximum:NaN,weapon:known,branchMasteries:{archery:41}}
 ])assert.equal(C.characterSheetPhysicalAttackRange(opts),null);
});
